#include "stdlib/blas/base/cdotc.h"
#include "stdlib/complex/float32/ctor.h"
#include "stdlib/complex/float32/real.h"
#include "stdlib/complex/float32/imag.h"
#include <stdio.h>

int main( void ) {
	stdlib_complex64_t x[ 2 ];
	stdlib_complex64_t y[ 2 ];
	stdlib_complex64_t dot;

	// Create complex arrays:
	x[ 0 ] = stdlib_complex64( 7.0f, -8.0f );
	x[ 1 ] = stdlib_complex64( -1.0f, -9.0f );

	y[ 0 ] = stdlib_complex64( 6.0f, -6.0f );
	y[ 1 ] = stdlib_complex64( -9.0f, 5.0f );

	// Compute the dot product:
	dot = c_cdotc( 2, (void *)x, 1, (void *)y, 1 );

	// Print the result:
	printf( "cdotc( x, y ) = %f + %fi\n", stdlib_complex64_real( dot ), stdlib_complex64_imag( dot ) );

	return 0;
}
